import pandas as pdfrom sqlalchemy.ext.asyncio import AsyncSessionfrom app.models import *  file_path: str = "data/clients.xlsx"async def import_excel_to_db(db: AsyncSession, file_path: str = "clients.xlsx"):    # Читаем по чанкам для большого файла    chunksize = 10000    # Импорт клиентов    for chunk in pd.read_excel(file_path, sheet_name='clients', chunksize=chunksize):        for _, row in chunk.iterrows():            client = Client(**row.to_dict())            db.add(client)        await db.commit()        # Аналогично для остальных листов с обработкой foreign keys    print("Импорт завершён")